#include <stdio.h>
#include <string.h>
#include <stdint.h>

/* Mirrors the frame layout GCC builds under -fstack-protector: locals,
   then an 8-byte canary, then (in a real function) the return address. */
struct frame {
    char buf[8];
    uint64_t canary;
};

static uint64_t master_canary = 0xDEADBEEFCAFEBABEULL;

/* buf is a fixed 8-byte target; memcpy performs no bounds check against it,
   exactly like an unguarded strcpy/gets. n is attacker-controlled. */
__attribute__((noinline))
static int echo(const char *input, size_t n) {
    struct frame f;
    f.canary = master_canary;         /* prologue: load canary */
    memcpy(f.buf, input, n);          /* vulnerable copy */
    if (f.canary != master_canary) {  /* epilogue: compare canary */
        fprintf(stderr, "*** stack smashing detected: canary now %016llx ***\n",
                (unsigned long long)f.canary);
        return -1;                    /* real glibc: __stack_chk_fail() -> abort() */
    }
    return 0;
}

int main(void) {
    printf("6-byte copy into buf[8]:  %s\n",
           echo("short", 6) == 0 ? "canary OK, safe return" : "SMASHED");
    printf("16-byte copy into buf[8]: %s\n",
           echo("AAAAAAAABBBBBBBB", 16) == 0 ? "canary OK, safe return" : "SMASHED");
    return 0;
}
